export const SIDES={top:'上边',bottom:'下边',left:'左边',right:'右边'};
export const DOOR_TYPES={inbound:{label:'入库门',color:'#c9e4f5'},outbound:{label:'出库门',color:'#f7d9bc'},general:{label:'通用门',color:'#f9e6a8'}};
export const edgeLength=(b,side)=>['top','bottom'].includes(side)?b.width:b.depth;
export function draggedDoorOffset(b,d,delta,snap=true){let offset=d.offset+delta;if(snap)offset=Math.round(offset*10)/10;return Math.max(0,Math.min(edgeLength(b,d.side)-d.width,offset));}
export function validateDoors(b){const doors=b.doors||[];if(!Array.isArray(doors))throw Error('门数据格式无效');const ids=new Set();for(const d of doors){if(!d.id||ids.has(d.id))throw Error('门标识重复');ids.add(d.id);if(typeof d.name!=='string'||!d.name.trim())throw Error('请填写门名称');if(!SIDES[d.side]||!DOOR_TYPES[d.type])throw Error('门的位置或用途无效');if(!Number.isFinite(d.offset)||!Number.isFinite(d.width)||d.offset<0||d.width<.5||d.offset+d.width>edgeLength(b,d.side)+1e-8)throw Error(`${d.name}：门宽至少 0.5 米，且门必须完整位于所选边上`);}for(const side of Object.keys(SIDES)){const sorted=doors.filter(d=>d.side===side).sort((a,b)=>a.offset-b.offset);for(let i=1;i<sorted.length;i++)if(sorted[i].offset<sorted[i-1].offset+sorted[i-1].width-1e-8)throw Error(`${SIDES[side]}的门相互重叠，请调整位置`);}}
export function edgePoints(b,side,start,end){if(side==='top'||side==='bottom'){const y=b.y+(side==='bottom'?b.depth:0);return [{x:b.x+start,y},{x:b.x+end,y}];}const x=b.x+(side==='right'?b.width:0);return [{x,y:b.y+start},{x,y:b.y+end}];}
export function wallSegments(b){const result=[];for(const side of Object.keys(SIDES)){let start=0;for(const door of (b.doors||[]).filter(d=>d.side===side).sort((a,b)=>a.offset-b.offset)){if(door.offset>start)result.push(edgePoints(b,side,start,door.offset));start=door.offset+door.width;}if(start<edgeLength(b,side))result.push(edgePoints(b,side,start,edgeLength(b,side)));}return result;}
export function newDoor(b){for(const side of ['bottom','top','left','right']){const length=edgeLength(b,side),doors=(b.doors||[]).filter(d=>d.side===side).sort((a,b)=>a.offset-b.offset);let start=0;for(const stop of [...doors.map(d=>({offset:d.offset,end:d.offset+d.width})),{offset:length,end:length}]){if(stop.offset-start>=.5){let i=1;while((b.doors||[]).some(d=>d.name===`门 ${i}`))i++;return {id:crypto.randomUUID(),name:`门 ${i}`,side,type:'general',offset:start,width:Math.min(3,stop.offset-start)};}start=stop.end;}}throw Error('边界上没有足够空间新增门');}
export function renderDoorEditor(container,b,api,esc,selectedId=null){container.innerHTML=`<h3>边界门 <span>${(b.doors||[]).length} 个</span></h3><p class="muted">上／下边的起点在左端；左／右边的起点在上端。偏移表示门开口起点距该端的距离。</p><button type="button" id="door-add">＋ 新增门</button>${(b.doors||[]).map(d=>`<button type="button" class="door-select ${selectedId===d.id?'active':''}" data-door-select="${d.id}">${esc(d.name)} · ${SIDES[d.side]}</button>`).join('')}${(b.doors||[]).filter(d=>!selectedId||selectedId===d.id).map(d=>`<form class="door-form" data-door-id="${d.id}"><div class="fields"><label class="wide">门名称<input name="name" value="${esc(d.name)}" required></label><label>所在边<select name="side">${Object.entries(SIDES).map(([k,v])=>`<option value="${k}" ${d.side===k?'selected':''}>${v}</option>`).join('')}</select></label><label>用途<select name="type">${Object.entries(DOOR_TYPES).map(([k,v])=>`<option value="${k}" ${d.type===k?'selected':''}>${v.label}</option>`).join('')}</select></label><label>起点偏移 / 米<input name="offset" type="number" min="0" step="any" value="${d.offset}" required></label><label>门宽 / 米<input name="width" type="number" min="0.5" step="any" value="${d.width}" required></label></div><div class="field-actions"><button class="primary">应用门设置</button><button type="button" data-door-delete="${d.id}" class="danger">删除门</button></div></form>`).join('')}`;container.querySelectorAll('[data-door-select]').forEach(button=>button.onclick=()=>api.onDoorSelect(button.dataset.doorSelect));container.querySelector('#door-add').onclick=()=>api.commit(()=>{const door=newDoor(b);b.doors??=[];b.doors.push(door);validateDoors(b);});container.querySelectorAll('.door-form').forEach(form=>{form.onsubmit=e=>{e.preventDefault();api.commit(()=>{const door=b.doors.find(d=>d.id===form.dataset.doorId),next={...door};for(const [k,v]of new FormData(form))next[k]=['offset','width'].includes(k)?Number(v):v.trim();validateDoors({...b,doors:b.doors.map(d=>d.id===next.id?next:d)});Object.assign(door,next);});};});container.querySelectorAll('[data-door-delete]').forEach(button=>button.onclick=()=>api.commit(()=>{b.doors=b.doors.filter(d=>d.id!==button.dataset.doorDelete);}));}
